package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.documents.*;import static com.rpb.reservation.workforce.documents.DocumentDtos.*;
import com.rpb.reservation.workforce.application.*;import static com.rpb.reservation.workforce.application.WorkforceDtos.*;
import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceEmployeeDocumentsPostgresTest extends WorkforcePostgresTest {
 EmployeeDocumentService docs;UUID employee,type;DocumentRepository documents;
 @BeforeEach void documents(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceEmployeeDocumentsPostgresTest.class)return;documents=new DocumentRepository(jdbc);docs=proxy(new EmployeeDocumentService(access,repository,documents,new WorkforceAudit(logs,new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules())));employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store),company,null,null));type=docs.types(admin,store).getFirst().id();}
 Write write(long version){return new Write(version,type,"S123",LocalDate.of(2030,1,1),"Optional",false);}
 @Test void defaultTypesOptionalDocumentsAndPrivateAttachmentsSupportVersionedRetries(){assertThat(docs.types(admin,store)).extracting(Type::name).containsExactlyInAnyOrder("身份证","护照","批文");assertThat(docs.list(admin,store,employee).items()).isEmpty();var id=UUID.randomUUID();var d=docs.save(admin,store,employee,id,write(0));assertThat(docs.save(admin,store,employee,id,write(0))).isEqualTo(d);var file=UUID.randomUUID();byte[] bytes="%PDF-1.7\nsynthetic fixture".getBytes(java.nio.charset.StandardCharsets.US_ASCII);var uploaded=docs.upload(admin,store,employee,id,file,1,"../../test.pdf",bytes);assertThat(uploaded.version()).isEqualTo(2);assertThat(uploaded.attachments()).hasSize(1);assertThat(docs.upload(admin,store,employee,id,file,1,"test.pdf",bytes).version()).isEqualTo(2);assertThat(docs.download(admin,store,employee,id,file).bytes()).isEqualTo(bytes);assertThat(docs.download(admin,store,employee,id,file).filename()).isEqualTo("test.pdf");assertThatThrownBy(()->docs.save(admin,store,employee,id,write(1))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);docs.deleteFile(admin,store,employee,id,file,new Version(2L));assertThatThrownBy(()->docs.download(admin,store,employee,id,file)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);}
 @Test void ownAccountCanMaintainButOtherEmployeesAndForeignStoresCannot(){var account=account("store_staff",Set.of(store),Set.of("workforce.view"));var own=new CurrentActor(tenant,account,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));var self=UUID.randomUUID();employees.save(admin,store,self,new EmployeeWrite(0L,"SELF","Self","","","Service",LocalDate.of(2026,10,1),null,"active",company,LocalDate.of(2026,10,1),store,List.of(store),account,"",""));assertThat(docs.list(own,store,self).items()).isEmpty();docs.save(own,store,self,UUID.randomUUID(),write(0));assertThatThrownBy(()->docs.list(own,store,employee)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThatThrownBy(()->docs.list(admin,sibling,self)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);assertThatThrownBy(()->docs.type(own,store,UUID.randomUUID(),new TypeWrite(0L,"Other",true,false))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
 @Test void disabledTypesRetainHistoryAndReferencedTypesCannotBeDeleted(){var id=UUID.randomUUID();docs.save(admin,store,employee,id,write(0));docs.type(admin,store,type,new TypeWrite(1L,docs.types(admin,store).getFirst().name(),false,false));docs.save(admin,store,employee,id,write(1));assertThatThrownBy(()->docs.save(admin,store,employee,UUID.randomUUID(),write(0))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->docs.type(admin,store,type,new TypeWrite(2L,"Old",false,true))).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_DOCUMENT_TYPE_IN_USE");}
 @Test void imageLimitAndInvalidFilesAreEnforcedBeforeStorage(){byte[] image=new byte[1048577];image[0]=(byte)255;image[1]=(byte)216;image[2]=(byte)255;assertThatThrownBy(()->DocumentFileRules.validate(UUID.randomUUID(),"image.jpg",image)).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_DOCUMENT_FILE_TOO_LARGE");assertThatThrownBy(()->DocumentFileRules.validate(UUID.randomUUID(),"file.png","<script>bad</script>".getBytes())).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_DOCUMENT_FILE_INVALID");}
 @Test void extendedProfileAndHireCorrectionRetainLegacyValues(){var c=command(0,List.of(store),company,null,null);var saved=employees.save(admin,store,employee,new EmployeeWrite(1L,c.employeeNo(),c.name(),c.phone(),c.email(),c.jobTitle(),LocalDate.of(2026,10,2),null,"active",company,c.companyEffectiveDate(),store,c.storeIds(),null,"","",null,LocalDate.of(1990,3,5),"Alice Tan",false));assertThat(saved.birthDate()).isEqualTo(LocalDate.of(1990,3,5));assertThat(saved.englishName()).isEqualTo("Alice Tan");assertThat(saved.enabled()).isFalse();assertThat(saved.hireDate()).isEqualTo(LocalDate.of(2026,10,2));var legacy=new EmployeeWrite(2L,saved.employeeNo(),saved.name(),saved.phone(),saved.email(),saved.jobTitle(),saved.hireDate(),saved.leaveDate(),saved.status(),saved.companyId(),saved.companyEffectiveDate(),store,saved.storeIds(),null,"","");assertThat(employees.save(admin,store,employee,legacy).birthDate()).isEqualTo(saved.birthDate());}
 @Test void managerScopeForeignTenantAndLinkedHistoryCannotBeBypassed(){var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,version) values(?,?,?,true,1)",tenant,store,managerId);var manager=new CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));var doc=UUID.randomUUID();docs.save(manager,store,employee,doc,new Write(0L,type,"",null,"",false));assertThat(docs.list(manager,store,employee).items()).hasSize(1);var foreign=new CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThatThrownBy(()->docs.list(foreign,store,employee)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);jdbc.update("insert into workforce_work_stores(employee_id,tenant_id,store_id,started_on) values(?,?,?,'2026-10-01')",employee,tenant,sibling);assertThatThrownBy(()->docs.list(manager,store,employee)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
 @Test void auditFailureRollsBackAndAppGateDenialsBlockPrivateDocuments(){var id=UUID.randomUUID();org.mockito.Mockito.doThrow(new IllegalStateException("audit failure")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThatThrownBy(()->docs.save(admin,store,employee,id,write(0))).isInstanceOf(IllegalStateException.class);assertThat(documents.list(tenant,employee)).isEmpty();for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->docs.list(admin,store,employee)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}}
 @Test void hireCorrectionCannotMovePastSchedulesAndBirthMustPrecedeHire(){var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();var audit=new WorkforceAudit(logs,mapper);var scheduling=new com.rpb.reservation.workforce.scheduling.SchedulingRepository(jdbc,new WorkforceJson(mapper));var shifts=proxy(new com.rpb.reservation.workforce.scheduling.ShiftService(access,scheduling,audit));var shift=shifts.save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.scheduling.SchedulingDtos.ShiftWrite(0L,"Day","09:00","17:00",false,"none",0,0,0,0,false,true));var roster=proxy(new com.rpb.reservation.workforce.scheduling.ScheduleService(access,scheduling,repository,audit,Clock.fixed(Instant.parse("2026-10-02T01:00:00Z"),ZoneOffset.UTC)));roster.save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.scheduling.SchedulingDtos.ScheduleWrite(0L,employee,shift.id(),LocalDate.of(2026,10,10),"scheduled"));var e=repository.find(tenant,employee).orElseThrow();assertThatThrownBy(()->employees.save(admin,store,employee,new EmployeeWrite(e.version(),e.employeeNo(),e.name(),e.phone(),e.email(),e.jobTitle(),LocalDate.of(2026,10,11),null,e.status(),e.companyId(),e.companyEffectiveDate(),store,e.storeIds(),null,"",""))).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_HIRE_DATE_IN_USE");assertThat(repository.find(tenant,employee).orElseThrow().hireDate()).isEqualTo(LocalDate.of(2026,10,1));assertThatThrownBy(()->employees.save(admin,store,employee,new EmployeeWrite(e.version(),e.employeeNo(),e.name(),e.phone(),e.email(),e.jobTitle(),e.hireDate(),null,e.status(),e.companyId(),e.companyEffectiveDate(),store,e.storeIds(),null,"","",e.positionId(),LocalDate.of(2030,1,1),"",true))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);}
}
